public static int szukajWzorca(String text, String wzor) {
    int n = text.length();
    int m = wzor.length();
    int j = 0;
    for (int i = 0; i <= n - m; i++) {
        while (j < m && text.charAt(i + j) == wzor.charAt(j)) {
            j++;
        }
        if (j == m) {
            return i;
        }
    }
    return -1;
}

